-- TORVO V2 purchase requirement foundation. Staging review required.
create table if not exists purchase_requirements (id uuid primary key default gen_random_uuid(),request_type text not null check(request_type in('existing_item','new_item')),existing_item_id uuid references catalog_items(id),requested_qty numeric not null check(requested_qty>0),reason_type text not null check(reason_type in('out_of_stock','low_stock','fast_moving','more_qty_required','new_item_required','dealer_demand','other')),reason text,status text not null default 'submitted' check(status in('submitted','under_review','approved','hold','rejected','purchasing','partially_purchased','completed')),requested_by uuid not null references app_users(id),approved_qty numeric,reviewed_by uuid references app_users(id),reviewed_at timestamptz,admin_note text,created_at timestamptz not null default now(),check((request_type='existing_item' and existing_item_id is not null) or request_type='new_item'));
create index if not exists idx_purchase_requirements_status on purchase_requirements(status,created_at desc);
create table if not exists purchase_requirement_new_items (requirement_id uuid primary key references purchase_requirements(id),company_brand text not null,machine_type text,model_no text,item_part_name text not null,oem_part_no text,category text,expected_market_demand text,photo_url text,market_note text,created_item_id uuid references catalog_items(id));
create table if not exists purchase_requirement_dealers (id uuid primary key default gen_random_uuid(),requirement_id uuid not null references purchase_requirements(id),dealer_id uuid not null references dealers(id),requested_qty numeric,note text,fulfilled_qty numeric not null default 0,stock_arrival_recorded_at timestamptz,unique(requirement_id,dealer_id));
create table if not exists purchase_requirement_links (id uuid primary key default gen_random_uuid(),requirement_id uuid not null references purchase_requirements(id),purchase_id uuid not null references purchase_headers(id),linked_by uuid not null references app_users(id),linked_at timestamptz not null default now(),unique(requirement_id,purchase_id));
